(()=>{function mount(){if(document.querySelector('.studio-intro'))return;const main=document.querySelector('main');if(!main)return;const intro=document.createElement('section');intro.className='studio-intro';intro.innerHTML='<h1>De una referencia a un hook que puedas escuchar.</h1><p>Carga una canción, define qué quieres componer y deja que HookLab conecte beat, melodía, texto y prosodia en propuestas comparables.</p>';const progress=document.createElement('nav');progress.className='studio-progress';progress.setAttribute('aria-label','Flujo de composición');progress.innerHTML='<span>1 Referencia</span><span>2 Intención</span><span>3 Hooks</span><span>4 Escucha</span><span>5 Decide</span><span>6 Exporta</span>';main.insertBefore(progress,main.firstChild);main.insertBefore(intro,progress);const warning=document.querySelector('.warning');if(warning){warning.innerHTML='<b>Modo experimental.</b> La referencia guía el estilo de la sesión. Las propuestas D0 son exploratorias y la decisión creativa sigue siendo del productor.'}const cards=[...document.querySelectorAll('.card')];const byStep=s=>cards.find(c=>c.querySelector('.step')?.textContent.includes(s));const objective=byStep('1 ·');const reference=byStep('2 ·');const evidence=byStep('3 ·');if(reference&&objective){reference.parentNode.insertBefore(reference,objective)}if(evidence){evidence.open=false;const h=evidence.querySelector('h2');if(h)h.textContent='Qué evidencia está usando HookLab';}const refTitle=reference?.querySelector('h2');if(refTitle)refTitle.textContent='Elige una referencia sonora';const objTitle=objective?.querySelector('h2');if(objTitle)objTitle.textContent='Describe el hook que quieres construir';const textLabel=objective?.querySelector('label:nth-of-type(2)');if(textLabel){const ta=textLabel.querySelector('textarea');textLabel.childNodes[0].textContent='Idea o frase inicial ';if(ta)ta.placeholder='Opcional. HookLab debe ayudarte a desarrollar la letra, no exigirla terminada.'}const intent=document.getElementById('intent');if(intent)intent.placeholder='Ej. reencuentro, esperanza contenida, íntimo';const midi=document.getElementById('midiBtn');if(midi)midi.textContent='Crear propuestas de hook';const build=byStep('4 ·');if(build){const h=build.querySelector('h2');if(h)h.textContent='Propuestas musicales';}const prosody=byStep('4B');if(prosody){const h=prosody.querySelector('h2');if(h)h.textContent='Ajusta letra y prosodia';}const dock=document.createElement('div');dock.className='studio-dock';dock.innerHTML='<div><b>HookLab Studio</b><small id="uxStatus">Empieza cargando una referencia</small></div><button id="uxNext">Ir a referencia</button>';document.body.appendChild(dock);const status=dock.querySelector('#uxStatus'),next=dock.querySelector('#uxNext');next.onclick=()=>{const target=document.getElementById('ref')?.closest('.card')||reference;target?.scrollIntoView({behavior:'smooth',block:'start'})};const ref=document.getElementById('ref'),an=document.getElementById('analyzeRef'),gen=document.getElementById('midiBtn'),save=document.getElementById('save');ref?.addEventListener('change',()=>{status.textContent='Referencia cargada · ahora analízala';next.textContent='Analizar referencia';next.onclick=()=>an?.click()});an?.addEventListener('click',()=>{status.textContent='Analizando beat y tempo…';setTimeout(()=>{status.textContent='Define la intención y crea propuestas';next.textContent='Ir a intención';next.onclick=()=>objective?.scrollIntoView({behavior:'smooth',block:'start'})},800)});gen?.addEventListener('click',()=>{status.textContent='Propuestas creadas · escucha y compara';next.textContent='Ir a propuestas';next.onclick=()=>build?.scrollIntoView({behavior:'smooth',block:'start'})});save?.addEventListener('click',()=>{status.textContent='Evaluación guardada';next.textContent='Exportar';next.onclick=()=>document.getElementById('export')?.click()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount()})();